#include <stddef.h>
#include <stdio.h>

enum Progress {
    NOT_STARTED,
    PRACTISING,
    CHECKED
};

struct Milestone {
    const char *topic;
    enum Progress progress;
    unsigned int evidence_count;
};

static const char *progress_name(enum Progress progress)
{
    switch (progress) {
    case NOT_STARTED: return "not started";
    case PRACTISING: return "practising";
    case CHECKED: return "checked";
    }
    return "invalid";
}

int main(void)
{
    const struct Milestone plan[] = {
        {"types", CHECKED, 3U},
        {"control flow", CHECKED, 4U},
        {"arrays", PRACTISING, 2U},
        {"pointers", NOT_STARTED, 0U},
        {"functions", NOT_STARTED, 0U}
    };
    const size_t count = sizeof plan / sizeof plan[0];
    size_t i;
    size_t checked = 0U;

    for (i = 0U; i < count; ++i) {
        printf("%s: %s (evidence=%u)\n", plan[i].topic,
               progress_name(plan[i].progress), plan[i].evidence_count);
        if (plan[i].progress == CHECKED) {
            ++checked;
        }
    }
    printf("checkpoint: %zu/%zu topics checked\n", checked, count);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

struct Revision {
    const char *topic;
    unsigned int last_practised_session;
    unsigned int interval;
};

static int is_due(const struct Revision *item, unsigned int current_session)
{
    if (item == NULL || item->topic == NULL || item->interval == 0U) {
        return 0;
    }
    return current_session >= item->last_practised_session &&
           current_session - item->last_practised_session >= item->interval;
}

int main(void)
{
    const struct Revision items[] = {
        {"arrays", 2U, 2U},
        {"pointers", 4U, 3U},
        {"functions", 5U, 1U}
    };
    const size_t count = sizeof items / sizeof items[0];
    const unsigned int current_session = 6U;
    size_t i;

    printf("revision session %u\n", current_session);
    for (i = 0U; i < count; ++i) {
        printf("%s: %s\n", items[i].topic,
               is_due(&items[i], current_session) ? "review" : "later");
    }
    return 0;
}
